const src = $json;
const body = src.body || {};
const headers = src.headers || {};

const cfg = {
  locationId: src.locationId,
  apiBaseUrl: String(src.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, ''),
  apiKey: src.apiKey,
  defaultDryRun: !!src.defaultDryRun,
  authHeaderName: String(src.authHeaderName || 'x-intake-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
};

if (!cfg.locationId) throw new Error('Missing Config.locationId');
if (!cfg.apiKey) throw new Error('Missing Config.apiKey');

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid intake auth header' } }];
}

const tagMap = {
  email_inbound: 'Warm Intake - Email Inbound',
  email_outbound: 'Warm Intake - Email Outbound',
  sms: 'Warm Intake - SMS',
  referral: 'Referral - Intake',
};
const allowedTags = new Set(Object.values(tagMap));

let intakeTag = String(body.intakeTag || body.tag || '').trim();
const intakeType = String(body.intakeType || body.type || '').trim().toLowerCase();
if (!intakeTag && intakeType && tagMap[intakeType]) intakeTag = tagMap[intakeType];

if (!intakeTag || !allowedTags.has(intakeTag)) {
  return [{
    json: {
      ok: false,
      error: 'invalid_tag',
      message: 'Provide a valid intakeTag',
      allowedTags: Array.from(allowedTags),
      acceptedTypes: Object.keys(tagMap),
    },
  }];
}

const dryRun = body.dryRun === undefined ? cfg.defaultDryRun : !!body.dryRun;

function clean(v) { return String(v || '').trim(); }
let contactId = clean(body.contactId);
const email = clean(body.email);
const phone = clean(body.phone);
const firstName = clean(body.firstName);
const lastName = clean(body.lastName);

if (!contactId && !email && !phone) {
  return [{ json: { ok: false, error: 'missing_contact', message: 'Provide contactId or email/phone' } }];
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

const headersGhl = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function apiRequest({ method, path, body }) {
  const options = {
    method,
    url: `${cfg.apiBaseUrl}${path}`,
    headers: headersGhl,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
    };
  }
}

let resolvedVia = 'contactId';
if (!contactId) {
  resolvedVia = 'upsert';
  const upsertBody = {
    locationId: cfg.locationId,
    email: email || undefined,
    phone: phone || undefined,
    firstName: firstName || undefined,
    lastName: lastName || undefined,
  };
  Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

  const upsert = await apiRequest.call(this, { method: 'POST', path: '/contacts/upsert', body: upsertBody });
  if (!upsert.ok) {
    return [{ json: { ok: false, error: 'upsert_failed', details: upsert.data } }];
  }
  contactId = upsert.data?.contact?.id || upsert.data?.id || upsert.data?.contactId || '';
  if (!contactId) {
    return [{ json: { ok: false, error: 'contact_id_missing_after_upsert', details: upsert.data } }];
  }
}

if (dryRun) {
  return [{
    json: {
      ok: true,
      dryRun: true,
      action: 'would_add_intake_tag',
      contactId,
      intakeTag,
      resolvedVia,
    },
  }];
}

const tagRes = await apiRequest.call(this, {
  method: 'POST',
  path: `/contacts/${contactId}/tags`,
  body: { tags: [intakeTag] },
});

if (!tagRes.ok) {
  return [{ json: { ok: false, error: 'tag_add_failed', contactId, intakeTag, details: tagRes.data } }];
}

return [{
  json: {
    ok: true,
    dryRun: false,
    action: 'intake_tag_added',
    contactId,
    intakeTag,
    resolvedVia,
    response: tagRes.data,
  },
}];

